import * as THREE from './vendor/three/three.module.js';
import {OrbitControls} from './vendor/three/OrbitControls.js';
const K=KitCore,host=document.querySelector('#kit3d');
host.innerHTML=`<div class="chem-title"><div><p class="eyebrow">06 / BYGG I ROMMET</p><h2>3D-molekylbyggesett</h2><p>Kuler, pinner og nye perspektiver. Bygg med hendene – på skjermen.</p></div><a href="#kitLibrary" class="chem-bank-link">Hent en ferdig modell ↓</a></div>
<div class="kit-layout"><aside class="kit-tools"><h3>Velg byggestein</h3><label>Atom og form<select id="kitPiece">${Object.entries(K.types).map(([key,t])=>`<option value="${key}">${t.name}</option>`).join('')}</select></label><label>Ny binding<select id="kitOrder"><option value="1">Enkelt · ett elektronpar</option><option value="2">Dobbel · to elektronpar</option><option value="3">Trippel · tre elektronpar</option></select></label><button id="kitStart">Legg til løs byggestein</button><p class="note">Velg en kule. Klikk deretter på et grønt festepunkt for å sette på byggesteinen du har valgt.</p><div id="kitSelection"></div><div class="kit-actions"><button id="kitConnect" aria-pressed="false">Koble to atomer</button><button id="kitRemove">Fjern valgt atom</button><button id="kitFill">Fyll ledige plasser med H</button></div><p class="note">Karbon: tetraeder for fire enkeltbindinger, plant for en dobbeltbinding, rett for en trippelbinding. Festepunktene viser retninger, ikke elektroner.</p></aside>
<div class="kit-main"><div class="kit-toolbar"><button id="kitUndo">↶ Angre</button><button id="kitClear">Tøm</button><button id="kitFit">Vis hele modellen</button><label>Dra for å<select id="kitMode"><option value="orbit">Rotere modellen</option><option value="move">Flytte én kule</option></select></label><label>Visning<select id="kitStyle"><option value="ball">Kuler og pinner</option><option value="space">Store kuler</option></select></label></div><p id="kitStatus" role="status">Dra i bakgrunnen for å rotere. Rull eller knip for å zoome.</p><div id="kitCanvas" aria-label="Tredimensjonalt molekylbyggesett"><p id="kitLoading">Laster 3D-visning …</p></div><div class="kit-view-controls"><button id="kitLeft" aria-label="Roter mot venstre">↶ Drei</button><button id="kitRight" aria-label="Roter mot høyre">Drei ↷</button><button id="kitUp">Se ovenfra</button><button id="kitZoomIn" aria-label="Zoom inn">＋</button><button id="kitZoomOut" aria-label="Zoom ut">−</button><label><input type="checkbox" id="kitLabels" checked> Atomsymboler</label><span id="kitCount"></span></div><p class="note">Mus: dra for å rotere, rull for å zoome, høyre musetast for å panorere. Berøring: dra med én finger, zoom/panorer med to. «Flytte én kule» flytter i skjermplanet; roter først for å velge en annen retning.</p><div id="kitInfo" class="kit-info"></div><div class="kit-files"><button id="kitSave">Lagre byggesett som fil</button><label class="kit-file">Åpne egen modell<input id="kitOpen" type="file" accept="application/json,.json"></label><span id="kitStorage" class="note"></span></div></div></div>
<section id="kitLibrary" class="chem-bank"><p class="eyebrow">MODELLBANKEN</p><h2>Fra metan til diamant</h2><p>Alle modellene kan roteres og bygges videre på. Å hente en modell kan angres.</p><div class="kit-library">${Object.entries(K.presets).map(([id,p])=>`<button data-kit-preset="${id}"><span class="kit-model-icon">${p.network?'⬡':id==='fullerene'?'◉':'⚭'}</span><strong>${p.name}</strong><span>${p.tag}</span><small>Hent modell →</small></button>`).join('')}</div></section>
<details class="kit-limits"><summary>Hva viser denne modellen?</summary><p>Kulene viser atomene og pinnene viser elektronparbindinger. Én, to eller tre parallelle pinner betyr én, to eller tre delte elektronpar. Elektronene selv vises ikke. Store kuler er en alternativ visning, ikke nøyaktige atomradier.</p><p>Dette er et idealisert byggesett med faste retninger. Det beregner ikke energi, stabilitet, korrekte bindingslengder eller molekylers bevegelse. Nitrogenbrikken bruker forenklede tetraedriske retninger. Du kan flytte kuler fritt; en omplassert modell trenger ikke vise stoffets virkelige form. Færre enn fullt antall bindinger betyr en uferdig modell, ikke automatisk et stabilt molekyl.</p><p>Grafen og grafitt vises som forbindelsesnettverk uten å angi alle π-bindingene. Diamant og grafitt er ikke små enkeltmolekyler. Avskårne kanter er utsnitt, ikke frie atomer i det virkelige materialet.</p><a href="https://www.open.edu/openlearn/mod/oucontent/view.php?id=72182&section=3.2" target="_blank" rel="noreferrer">Karbonstrukturer · Open University ↗</a> · <a href="https://openstax.org/books/chemistry-2e/pages/7-6-molecular-structure-and-polarity" target="_blank" rel="noreferrer">Molekylgeometri · OpenStax ↗</a><p class="note">3D-visning: Three.js (MIT), lagret lokalt med appen.</p></details>`;
const q=id=>host.querySelector('#'+id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let m=K.presets.methane.make(),preset='methane',selected=0,bondSelected=null,connecting=false,history=[],pointer=null;
const storageKey='atomverksted-kit3d-v1';
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved){m=K.validate(saved.model);preset=null;}}catch{}
function message(s){q('kitStatus').textContent=s}
function remember(){history.push(JSON.stringify({m,preset,selected}));if(history.length>40)history.shift()}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({model:m}));q('kitStorage').textContent='Lagres automatisk i denne nettleseren.'}catch{q('kitStorage').textContent='Automatisk lagring er utilgjengelig. Bruk «Lagre byggesett som fil».'}}
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});}catch{q('kitLoading').textContent='Nettleseren kunne ikke starte 3D-grafikk (WebGL). Prøv en annen nettleser eller slå på maskinvareakselerasjon. Det vanlige molekylverkstedet fungerer fortsatt.';throw Error('3D-visning krever WebGL');}
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor('#f0f4ee');q('kitLoading').remove();q('kitCanvas').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','3D-modell. Velg også atomer og festepunkter med kontrollene til venstre.');
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(38,1,.1,1000),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=false;controls.minDistance=2;controls.maxDistance=180;
scene.add(new THREE.HemisphereLight(0xffffff,0x637465,2.5));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(5,10,8);scene.add(light);
const group=new THREE.Group();scene.add(group);let picks=[];const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();
const sphere=new THREE.SphereGeometry(1,24,16),cylinder=new THREE.CylinderGeometry(1,1,1,12),materials={};
function mat(color,opacity=1){const key=color+':'+opacity;return materials[key]??(materials[key]=new THREE.MeshStandardMaterial({color,roughness:.36,metalness:.05,transparent:opacity<1,opacity}))}
function render(){if(!host.hidden)renderer.render(scene,camera)}
function resize(){const box=q('kitCanvas').getBoundingClientRect();if(!box.width||!box.height)return;renderer.setSize(box.width,box.height);camera.aspect=box.width/box.height;camera.updateProjectionMatrix();render()}
new ResizeObserver(resize).observe(q('kitCanvas'));controls.addEventListener('change',render);
function label(text){const canvas=document.createElement('canvas');canvas.width=128;canvas.height=64;const c=canvas.getContext('2d');c.fillStyle='#123c35';c.font='bold 38px sans-serif';c.textAlign='center';c.fillText(text,64,45);const texture=new THREE.CanvasTexture(canvas),sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,depthTest:false}));sprite.scale.set(.65,.325,1);sprite.userData.label=true;return sprite}
function ball(pos,r,color,data,opacity=1){const mesh=new THREE.Mesh(sphere,mat(color,opacity));mesh.position.fromArray(pos);mesh.scale.setScalar(r);mesh.userData=data;group.add(mesh);if(data.kind)picks.push(mesh);return mesh}
function stick(a,b,color,data,r=.075){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),dir=B.clone().sub(A),mesh=new THREE.Mesh(cylinder,mat(color));mesh.position.copy(A.add(B).multiplyScalar(.5));mesh.scale.set(r,dir.length(),r);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.normalize());mesh.userData=data;group.add(mesh);if(data.kind)picks.push(mesh)}
function rebuild(){for(const obj of [...group.children]){group.remove(obj);if(obj.userData.label){obj.material.map.dispose();obj.material.dispose()}}picks=[];const space=q('kitStyle').value==='space';
 m.bonds.forEach(([a,b,order],i)=>{const A=m.atoms[a].pos,B=m.atoms[b].pos,axis=K.unit(K.sub(B,A)),offset=K.mul(K.unit(K.cross(axis,Math.abs(axis[1])<.9?[0,1,0]:[1,0,0])),.17);for(let k=0;k<order;k++){const shift=K.mul(offset,k-(order-1)/2);stick(K.add(A,shift),K.add(B,shift),i===bondSelected?'#dc9630':'#91a59a',{kind:'bond',index:i})}});
 m.atoms.forEach((a,i)=>{const t=K.types[a.type],r=(t.symbol==='H'?.22:.36)*(space?2.35:1);if(i===selected)ball(a.pos,r*1.16,'#d5a149',{},.4);ball(a.pos,r,t.color,{kind:'atom',index:i});if(q('kitLabels').checked){const s=label(t.symbol);s.position.fromArray(K.add(a.pos,[0,r+.15,0]));group.add(s)}});
 if(selected!==null&&m.atoms[selected]&&!space&&!connecting){for(const slot of K.free(m,selected)){const a=m.atoms[selected],pos=K.add(a.pos,K.mul(a.dirs[slot],1.65));stick(a.pos,pos,'#aac6a6',{},.025);ball(pos,.18,'#4e9c76',{kind:'slot',slot},.6)}}
 const a=m.atoms[selected];q('kitSelection').innerHTML=`<label>Valgt atom<select id="kitAtom"><option value="">Ingen</option>${m.atoms.map((a,i)=>`<option value="${i}" ${i===selected?'selected':''}>${K.types[a.type].symbol} · ${i+1}</option>`).join('')}</select></label>${a?`<p><b>${K.types[a.type].name}</b><br>${K.neighbors(m,selected).length} naboer · ${K.used(m,selected)} av ${K.types[a.type].max} bindinger</p><div class="kit-sockets">${K.free(m,selected).map(s=>`<button data-kit-slot="${s}">＋ Festepunkt ${s+1}</button>`).join('')}</div>`:'<p>Velg en kule, eller legg til en byggestein.</p>'}${bondSelected!==null?`<p>Valgt binding: atom ${m.bonds[bondSelected][0]+1}–${m.bonds[bondSelected][1]+1}</p><button id="kitRemoveBond">Fjern valgt binding</button>`:''}`;
 q('kitAtom').onchange=e=>{selected=e.target.value===''?null:+e.target.value;bondSelected=null;connecting=false;rebuild()};host.querySelectorAll('[data-kit-slot]').forEach(b=>b.onclick=()=>attach(+b.dataset.kitSlot));if(q('kitRemoveBond'))q('kitRemoveBond').onclick=()=>change(()=>{m.bonds.splice(bondSelected,1);bondSelected=null});
 q('kitRemove').disabled=!a;q('kitConnect').disabled=!a;q('kitConnect').setAttribute('aria-pressed',String(connecting));q('kitUndo').disabled=!history.length;q('kitFill').disabled=!m.atoms.length||m.kind==='network';q('kitCount').textContent=`${m.atoms.length} kuler · ${m.bonds.length} koblinger`;
 const p=K.presets[preset];q('kitInfo').innerHTML=`<p class="eyebrow">${m.kind==='network'?'UTSNITT AV ET ATOMNETTVERK':'MOLEKYLBYGGESETT'}</p><h3>${p?escape(p.name):'Din modell'} <span>${m.kind==='network'?'':escape(K.formula(m))}</span></h3><p>${p?escape(p.text):'Du har endret byggesettet. Antall kuler og bindinger beskriver modellen, men bekrefter ikke at den er stabil eller har riktig romlig form.'}</p>${m.kind==='network'?'<p class="note">Antall kuler gjelder bare utsnittet. Åpne plasser ved kanten viser at nettverket fortsetter. I grafitt/grafen viser pinnene naboer, ikke full elektronbokføring.</p>':''}${p?`<a href="${p.source}" target="_blank" rel="noreferrer">Les om strukturene ↗</a>`:''}`;render();}
function change(fn){const before=JSON.stringify(m);remember();const error=fn();if(error){m=JSON.parse(before);history.pop();message(error);return false}preset=null;persist();rebuild();message('Modellen er oppdatert. Dra i bakgrunnen for å se den fra en annen side.');return true}
function attach(slot){if(change(()=>K.attach(m,selected,slot,q('kitPiece').value,+q('kitOrder').value))){selected=m.atoms.length-1;rebuild()}}
function fit(){if(!m.atoms.length){controls.target.set(0,0,0);camera.position.set(5,4,7)}else{const box=new THREE.Box3();m.atoms.forEach(a=>box.expandByPoint(new THREE.Vector3(...a.pos)));const center=box.getCenter(new THREE.Vector3()),radius=box.getSize(new THREE.Vector3()).length()/2+.85,aspect=q('kitCanvas').clientWidth/q('kitCanvas').clientHeight||1,halfFov=Math.atan(Math.tan(camera.fov*Math.PI/360)*Math.min(1,aspect)),distance=radius/Math.sin(halfFov)*1.12;controls.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(.8,.55,1).normalize().multiplyScalar(distance))}controls.update();resize()}
function hit(ev){const r=renderer.domElement.getBoundingClientRect();mouse.set((ev.clientX-r.left)/r.width*2-1,-(ev.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);return ray.intersectObjects(picks)[0]}
function pick(data){if(!data)return;if(data.kind==='slot'){attach(data.slot);return}if(data.kind==='bond'){selected=null;bondSelected=data.index;connecting=false;rebuild();message('Binding valgt. Du kan fjerne den med knappen til venstre.');return}if(connecting&&selected!==null){const error=K.canLink(m,selected,data.index,+q('kitOrder').value);if(error){message(error);return}change(()=>{m.bonds.push([selected,data.index,+q('kitOrder').value]);connecting=false});return}selected=data.index;bondSelected=null;rebuild();message('Atom valgt. Klikk på et grønt festepunkt for å bygge videre.')}
renderer.domElement.addEventListener('pointerdown',ev=>{if(!ev.isPrimary||ev.button!==0)return;const h=hit(ev);pointer={id:ev.pointerId,x:ev.clientX,y:ev.clientY,data:h?.object.userData,moved:false};if(q('kitMode').value==='move'&&pointer.data?.kind==='atom'){controls.enabled=false;selected=pointer.data.index;pointer.before=K.clone(m);pointer.oldPreset=preset;pointer.plane=new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()),new THREE.Vector3(...m.atoms[selected].pos));pointer.start=ray.ray.intersectPlane(pointer.plane,new THREE.Vector3());pointer.origin=[...m.atoms[selected].pos];renderer.domElement.setPointerCapture(ev.pointerId)}},true);
renderer.domElement.addEventListener('pointermove',ev=>{if(!pointer||ev.pointerId!==pointer.id)return;const d=pointer;if(Math.hypot(ev.clientX-d.x,ev.clientY-d.y)>5)d.moved=true;if(d.plane&&d.moved){if(!d.saved){remember();d.saved=true}hit(ev);const at=ray.ray.intersectPlane(d.plane,new THREE.Vector3());if(at&&d.start){const shift=at.sub(d.start);m.atoms[selected].pos=K.add(d.origin,shift.toArray());rebuild()}}});
renderer.domElement.addEventListener('pointerup',ev=>{if(!pointer||pointer.id!==ev.pointerId)return;const d=pointer;pointer=null;controls.enabled=true;if(d.plane&&d.moved){preset=null;persist();rebuild();message('Kulen er flyttet. Bindingene er beholdt; geometrien er nå din egen.')}else if(!d.moved)pick(d.data)});
renderer.domElement.addEventListener('pointercancel',()=>{if(pointer?.saved){m=pointer.before;preset=pointer.oldPreset;history.pop();rebuild()}pointer=null;controls.enabled=true});
q('kitStart').onclick=()=>{if(m.atoms.length>=240)return message('Maksimalt 240 atomer.');change(()=>{const max=m.atoms.length?Math.max(...m.atoms.map(a=>a.pos[0]))+3:0;m.atoms.push(K.atom(q('kitPiece').value,[max,0,0]));selected=m.atoms.length-1;bondSelected=null});fit()};
q('kitConnect').onclick=()=>{connecting=!connecting;rebuild();message(connecting?'Klikk på det andre atomet for å koble dem sammen. Retninger og lengder blir ikke automatisk tilpasset.':'Koblingsvalget er avbrutt.')};
q('kitRemove').onclick=()=>change(()=>{K.remove(m,selected);selected=null;bondSelected=null;connecting=false});
q('kitFill').onclick=()=>{if(change(()=>K.saturate(m)))fit()};
q('kitClear').onclick=()=>{change(()=>{m=K.model();selected=null;bondSelected=null;connecting=false});fit()};
q('kitUndo').onclick=()=>{if(!history.length)return;const h=JSON.parse(history.pop());m=h.m;preset=h.preset;selected=h.selected;bondSelected=null;connecting=false;persist();rebuild();fit();message('Siste endring er angret.')};
q('kitFit').onclick=fit;q('kitStyle').onchange=rebuild;q('kitLabels').onchange=rebuild;
function orbit(angle){const offset=camera.position.clone().sub(controls.target).applyAxisAngle(new THREE.Vector3(0,1,0),angle);camera.position.copy(controls.target).add(offset);controls.update()}
q('kitLeft').onclick=()=>orbit(-Math.PI/8);q('kitRight').onclick=()=>orbit(Math.PI/8);q('kitUp').onclick=()=>{const distance=camera.position.distanceTo(controls.target);camera.position.copy(controls.target).add(new THREE.Vector3(0,distance,.001));controls.update()};for(const [id,factor]of[['kitZoomIn',.8],['kitZoomOut',1.25]])q(id).onclick=()=>{const v=camera.position.clone().sub(controls.target);v.setLength(Math.max(2,Math.min(180,v.length()*factor)));camera.position.copy(controls.target).add(v);controls.update()};
host.querySelectorAll('[data-kit-preset]').forEach(b=>b.onclick=()=>{remember();preset=b.dataset.kitPreset;m=K.presets[preset].make();selected=null;bondSelected=null;connecting=false;persist();rebuild();fit();message(`${K.presets[preset].name} er hentet. Velg en kule for å se naboene og bygge videre.`);q('kitCanvas').scrollIntoView({behavior:'smooth',block:'center'})});
q('kitSave').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,model:m},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mitt-molekylbyggesett.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
q('kitOpen').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>250000)throw Error('Filen er for stor.');const data=JSON.parse(await file.text()),loaded=K.validate(data.model);change(()=>{m=loaded;selected=null;bondSelected=null;connecting=false});fit();message('Din lagrede modell er åpnet.')}catch(error){message('Kunne ikke åpne modellen: '+error.message)}ev.target.value=''};
window.addEventListener('resize',resize);rebuild();fit();persist();
